package com.haolin.vontlocal;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;

/** UI/negative service tests only. No real credentials or test hooks in the app. */
public final class FocusAcceptance extends UiAcceptance {
    int previewWidth;
    void waitFocus(String phase)throws Exception{long until=SystemClock.elapsedRealtime()+8000;while(SystemClock.elapsedRealtime()<until){if(FocusStore.state(context()).optString("phase").equals(phase))return;SystemClock.sleep(100);}throw new IOException("Focus did not become "+phase+": "+FocusStore.state(context()));}
    Button button(Activity a,String label){for(View v:nodes(a.getWindow().getDecorView()))if(v instanceof Button&&((Button)v).getText().toString().equals(label))return(Button)v;throw new IllegalArgumentException(label);}
    void fixtureScene(String id)throws Exception{JSONObject s=new JSONObject().put("action",id).put("completed",true).put("source","emulator-preview").put("vont",new JSONObject().put("status","success")).put("screenbar",new JSONObject().put("status","success"));ScreenbarClient.atomic(new File(context().getFilesDir(),LinkStore.STATUS),s.toString().getBytes("UTF-8"));}
    void cleanFocus()throws Exception{main(()->{FocusService.end(context(),"验收结束");return true;});SystemClock.sleep(200);ScreenbarClient.atomic(new File(context().getFilesDir(),FocusStore.FILE),"{}".getBytes("UTF-8"));}
    void widgetState(String phase,boolean wide,Map<Integer,Rect> reference)throws Exception{
        cleanFocus();ScreenbarClient.atomic(new File(context().getFilesDir(),LinkStore.STATUS),"{}".getBytes("UTF-8"));
        if(!phase.equals("idle")){main(()->{FocusPolicy.Session s=FocusStore.gate.begin("preview-"+phase,new FocusPolicy.Settings(50,5,30,3500),100,4500);s.ready(phase,SystemClock.elapsedRealtime(),System.currentTimeMillis());FocusStore.publish(context(),s,"模拟器状态预览");return true;});}
        HomeActivity home=(HomeActivity)open(HomeActivity.class);main(()->{Ui u=new Ui(home);LinearLayout root=u.root(home);root.setPadding(Ui.dp(home,16),Ui.dp(home,20),Ui.dp(home,16),0);u.text(root,"横向组件 · "+(phase.equals("idle")?"待开启":phase.equals("working")?"工作中":"休息中"),22);u.hint(root,"模拟器状态预览，未连接真实灯具");View view=LinkWidget.views(home,wide,previewWidth>0?previewWidth:wide?360:180).apply(home,root);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(Ui.dp(home,previewWidth>0?previewWidth:wide?360:180),Ui.dp(home,wide?124:188));lp.topMargin=Ui.dp(home,20);root.addView(view,lp);return true;});waitForIdleSync();
        main(()->{int[] ids={R.id.widget_work,R.id.widget_wind_down,R.id.widget_sleep,R.id.widget_off,R.id.widget_focus_action};int[] origin=new int[2];home.findViewById(R.id.widget_root).getLocationOnScreen(origin);for(int id:ids){View v=home.findViewById(id);int[] xy=new int[2];v.getLocationOnScreen(xy);Rect rect=new Rect(xy[0]-origin[0],xy[1]-origin[1],xy[0]-origin[0]+v.getWidth(),xy[1]-origin[1]+v.getHeight());check(v.getHeight()>=Ui.dp(home,44)&&v.getWidth()>=Ui.dp(home,44),"widget touch target "+id);check(v.hasOnClickListeners(),"widget action wired "+id);if(wide){if(reference.containsKey(id))check(reference.get(id).equals(rect),"widget control does not jump between phases "+id);else reference.put(id,rect);}}
            for(View v:nodes(home.findViewById(R.id.widget_root)))if(v instanceof TextView){TextView t=(TextView)v;if(t.getText().length()==0)continue;check(t.getLayout()!=null&&t.getLayout().getHeight()+t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()<=t.getHeight(),"widget text fits vertically: "+t.getText());}
            if(wide){View a=home.findViewById(R.id.widget_work),b=home.findViewById(R.id.widget_wind_down),c=home.findViewById(R.id.widget_sleep);check(a.getWidth()==b.getWidth()||Math.abs(a.getWidth()-b.getWidth())<=1,"scene equal widths");check(Math.abs(b.getWidth()-c.getWidth())<=1,"scene equal widths 2");int[] ax=new int[2],tx=new int[2],off=new int[2],cx=new int[2];a.getLocationOnScreen(ax);home.findViewById(R.id.widget_title_area).getLocationOnScreen(tx);home.findViewById(R.id.widget_off).getLocationOnScreen(off);c.getLocationOnScreen(cx);check(ax[0]==tx[0],"header and scenes share left inset");View bottom=home.findViewById(R.id.widget_reminder_row);int[] bx=new int[2];bottom.getLocationOnScreen(bx);check(bx[0]+bottom.getWidth()==off[0]+home.findViewById(R.id.widget_off).getWidth(),"rows share right inset");}return true;});
        screenshot("widget-"+(wide?"wide":"compact")+"-"+phase+"-"+Ui.appearance(context())+(previewWidth>0?"-min":""));finishActive();cleanFocus();
    }
    @Override public void onStart(){int code=0;try{
        if(!(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish")))throw new IOException("Emulator only");folder=new File(context().getFilesDir(),"ui-acceptance");folder.mkdirs();report.put("runId",runId).put("fontScale",context().getResources().getConfiguration().fontScale).put("scope","Emulator UI, offline service behavior, and model previews; physical lighting and lock-screen behavior deferred");
        check(!new File(context().getFilesDir(),ScreenbarClient.SEALED).exists(),"no physical lamp credential on emulator");SceneStore.ensure(context());FocusStore.saveSettings(context(),new FocusPolicy.Settings(50,5,30,3500));cleanFocus();
        String before=LinkStore.status(context()).toString();final FocusSettingsActivity editor=(FocusSettingsActivity)open(FocusSettingsActivity.class);check(main(()->editor.work.getText().toString().equals("50")&&editor.rest.getText().toString().equals("5")&&editor.brightness.getText().toString().equals("30")&&editor.temperature.getText().toString().equals("3500")),"focus defaults shown");
        main(()->{editor.work.setText("0");editor.save();return true;});check(FocusStore.settings(context()).workMinutes==50,"invalid focus input not persisted");main(()->{editor.work.setText("47");editor.rest.setText("7");editor.brightness.setText("23");editor.temperature.setText("3100");editor.save();return true;});active=null;check(FocusStore.settings(context()).workMinutes==47&&FocusStore.settings(context()).restMinutes==7&&FocusStore.settings(context()).restBrightness==23&&FocusStore.settings(context()).restTemperature==3100,"focus custom settings saved");check(before.equals(LinkStore.status(context()).toString()),"saving focus settings sends no lighting command");FocusStore.saveSettings(context(),new FocusPolicy.Settings(50,5,30,3500));
        // A widget start really launches the confirmation Activity, without touching light state.
        SystemClock.sleep(2200);final HomeActivity firstHome=(HomeActivity)open(HomeActivity.class);fixtureScene("bed");String bed=LinkStore.status(context()).toString();ActivityMonitor monitor=addMonitor(FocusConfirmActivity.class.getName(),null,false);main(()->{FocusConfirmActivity.pending(context()).send();return true;});FocusConfirmActivity confirm=(FocusConfirmActivity)waitForMonitorWithTimeout(monitor,3000);removeMonitor(monitor);check(confirm!=null,"widget start launches confirmation Activity");active=confirm;check(text(confirm,"切换到办公"),"bed requires explicit office switch confirmation");check(!FocusStore.running()&&bed.equals(LinkStore.status(context()).toString()),"opening confirmation does not change scene or countdown");screenshot("widget-start-confirm-bed");main(()->{button(confirm,"保持当前状态").performClick();return true;});active=null;check(!FocusStore.running()&&bed.equals(LinkStore.status(context()).toString()),"cancel confirmation preserves lights and timing");main(()->{firstHome.finish();return true;});
        // Confirm an actual service start: offline lamps must cause a clear failure, not a cycle.
        FocusConfirmActivity go=(FocusConfirmActivity)open(FocusConfirmActivity.class);main(()->{go.confirm();return true;});active=null;waitFocus("failed");check(!FocusStore.running(),"unconfirmed office preparation never starts cycle");check(LinkStore.plan(context()).optLong("endEpochSeconds")==0,"failed preparation arms no native timer");
        main(()->{FocusService.start(context(),new FocusPolicy.Settings(50,5,30,3500),100,4500);FocusService.end(context(),"结束测试");return true;});SystemClock.sleep(900);check(!FocusStore.running(),"end during preparation invalidates pending start");
        main(()->{FocusPolicy.Session s=FocusStore.gate.begin("end-preserves",new FocusPolicy.Settings(50,5,30,3500),100,4500);s.ready("resting",SystemClock.elapsedRealtime(),System.currentTimeMillis());FocusStore.publish(context(),s,"测试状态");return true;});String noCommand=LinkStore.status(context()).toString();main(()->{FocusService.end(context(),"提醒已结束，保留当前灯光");return true;});check(noCommand.equals(LinkStore.status(context()).toString()),"end alone does not submit a light operation");
        main(()->{FocusPolicy.Session s=FocusStore.gate.begin("scene-switch",new FocusPolicy.Settings(50,5,30,3500),100,4500);s.ready("resting",SystemClock.elapsedRealtime(),System.currentTimeMillis());FocusStore.publish(context(),s,"测试状态");LinkService.start(context(),"wind_down","emulator-test",false);return true;});check(!FocusStore.running(),"scene switch immediately invalidates focus");waitStatus("wind_down",System.currentTimeMillis()-1000);check(!FocusStore.running(),"scene completion cannot restart focus");
        main(()->{FocusPolicy.Session s=FocusStore.gate.begin("all-off",new FocusPolicy.Settings(50,5,30,3500),100,4500);s.ready("working",SystemClock.elapsedRealtime(),System.currentTimeMillis());FocusStore.publish(context(),s,"测试状态");LinkService.start(context(),"off","emulator-test",false);return true;});check(!FocusStore.running(),"all-off invalidates focus");waitStatus("off",System.currentTimeMillis()-1000);
        JSONObject stale=new JSONObject().put("active",true).put("sessionId","dead-process").put("phase","working");ScreenbarClient.atomic(new File(context().getFilesDir(),FocusStore.FILE),stale.toString().getBytes("UTF-8"));check(FocusStore.state(context()).optString("phase").equals("interrupted")&&!FocusStore.running(),"process death never replays a previous focus session");finishActive();cleanFocus();offlineServiceChecks();
        for(String theme:new String[]{"light","dark"}){context().getSharedPreferences("appearance-v1",0).edit().putString("theme",theme).commit();Map<Integer,Rect> positions=new HashMap<>();for(String phase:new String[]{"idle","working","resting"})widgetState(phase,true,positions);widgetState("idle",false,new HashMap<>());previewWidth=260;widgetState("idle",true,new HashMap<>());previewWidth=140;widgetState("idle",false,new HashMap<>());previewWidth=0;open(FocusSettingsActivity.class);screenshot("focus-settings-"+theme);finishActive();}
        context().getSharedPreferences("appearance-v1",0).edit().putString("theme","light").commit();final FocusSettingsActivity keyboard=(FocusSettingsActivity)open(FocusSettingsActivity.class);main(()->{keyboard.work.requestFocus();((android.view.inputmethod.InputMethodManager)keyboard.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(keyboard.work,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);return true;});SystemClock.sleep(800);check(main(()->keyboard.getWindow().getDecorView().getRootWindowInsets().isVisible(WindowInsets.Type.ime())),"keyboard displayed");main(()->{Rect frame=new Rect();keyboard.getWindow().getDecorView().getWindowVisibleDisplayFrame(frame);Button b=button(keyboard,"保存提醒参数");int[] xy=new int[2];b.getLocationOnScreen(xy);check(xy[1]+b.getHeight()<=frame.bottom,"save button above keyboard");return true;});screenshot("focus-settings-keyboard");finishActive();
        open(HomeActivity.class);screenshot("home-08");finishActive();SleepActivity office=(SleepActivity)open(SleepActivity.class,"sceneId","work");check(text(office,"提醒休息")&&text(office,"设置提醒参数"),"focus is in office secondary settings");screenshot("office-settings-08");finishActive();cleanFocus();
        report.put("status","passed").put("checkCount",count).put("checks",checks).put("physicalLampTested",false).put("softwareSchedulerModelTestedSeparately",true);
    }catch(Exception e){code=1;try{report.put("status","failed").put("error",e.toString()).put("checks",checks);}catch(Exception ignored){}}
        try{ScreenbarClient.atomic(new File(context().getFilesDir(),"focus-ui-report.json"),report.toString(2).getBytes("UTF-8"));}catch(Exception e){code=1;}Bundle result=new Bundle();result.putString("result",report.toString());finish(code,result);
    }
}
